function createServer(options: { allowAdmin?: boolean; rateLimit?: boolean } = {}) {
  const db = new MemoryAdapter();
  const secfn = createSecFnServer({
    db,
    encryption: { masterKey: "test-master-key", keyId: "test" },
    context: (request) => ({
      actorId: request.headers.get("x-actor-id") ?? undefined,
      tenantId: request.headers.get("x-tenant-id") ?? "tenant-a",
      namespace: request.headers.get("x-namespace") ?? "workspace-a",
      ip: request.headers.get("x-forwarded-for") ?? "127.0.0.1",
      userAgent: request.headers.get("user-agent") ?? undefined,
      requestId: request.headers.get("x-request-id") ?? undefined,
    }),
    authorize: async () => options.allowAdmin ?? true,
    rateLimit: options.rateLimit
      ? {
        enabled: true,
        persistence: db,
        windowMs: 60_000,
        limits: { perIP: 1, perUser: 1, perEndpoint: 1 },
      }
      : undefined,
  });
  return { db, secfn };
}

describe("createSecFnServer", () => {
  it("fails closed on admin routes when no authorize callback is configured", async () => {
    const db = new MemoryAdapter();
    const secfn = createSecFnServer({
      db,
      encryption: { masterKey: "test-master-key", keyId: "test" },
      context: () => ({ tenantId: "tenant-a", namespace: "workspace-a", ip: "127.0.0.1" }),
      // no authorize, no unsafeAllowUnauthenticatedAdmin
    });

    const response = await secfn.router.handle(new Request("https://app.test/secfn/admin/secrets"));
    expect(response.status).toBe(403);
    expect(db.dump("secfn_audit_events")[0]).toMatchObject({
      type: "permission_denied",
      metadata: { reason: "no_authorize_callback" },
    });
  });

  it("serves admin routes without authorize only when explicitly opted in", async () => {
    const secfn = createSecFnServer({
      db: new MemoryAdapter(),
      encryption: { masterKey: "test-master-key", keyId: "test" },
      context: () => ({ tenantId: "tenant-a", namespace: "workspace-a", ip: "127.0.0.1" }),
      unsafeAllowUnauthenticatedAdmin: true,
    });

    const response = await secfn.router.handle(new Request("https://app.test/secfn/admin/secrets"));
    expect(response.status).toBe(200);
  });

  it("requires the dedicated reveal action for secret sets", async () => {
    const denied: string[] = [];
    const db = new MemoryAdapter();
    const secfn = createSecFnServer({
      db,
      encryption: { masterKey: "test-master-key", keyId: "test" },
      context: () => ({ actorId: "admin", tenantId: "tenant-a", namespace: "workspace-a", ip: "127.0.0.1" }),
      // Grant everything except secret-sets:reveal.
      authorize: async (_ctx, action) => {
        if (action === "secret-sets:reveal") {
          denied.push(action);
          return false;
        }
        return true;
      },
    });
    const secret = await secfn.vault.createSecret({
